<script module lang="ts">
/**
 * An in-thread request to allow an agent action (`design/components/approval-card.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/approval-card.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy, type Snippet } from 'svelte'

import { Icon, agentMember, joinSlot, watchEffect } from '@polymorph/svelte'
import styles from '@polymorph/recipes/ai/approval-card.module.css'
import Button from '../controls/Button.svelte'

export type ApprovalDecision = NonNullable<ApprovalCardProps['decision']>

export type ApprovalTone = NonNullable<ApprovalCardProps['tone']>

export interface ApprovalCardProps {
  /**
   * The approve button's text (generic default `Allow`), which localized hosts replace.
   */
  approveLabel?: string
  /**
   * The details, such as a ToolCall, a CodeBlock or a DescriptionList.
   */
  children?: Snippet
  /**
   * The recorded decision, which replaces the actions with the outcome.
   */
  decision?: 'denied' | 'approved'
  /**
   * The deny button's text (generic default `Deny`).
   */
  denyLabel?: string
  description?: string
  /**
   * The outcome text for each decision (generic defaults `Allowed` / `Denied`).
   */
  messages?: { approved: string; denied: string }
  onApprove?: () => void
  onDeny?: () => void
  /**
   * The decision being sent, which puts that button in its loading state and disables the other.
   */
  pending?: 'denied' | 'approved'
  /**
   * The action, phrased as a question the reader can answer, such as "Run `rm -rf dist`?"
   */
  title: string
  /**
   * `warning` for a normal request, `danger` for an action that cannot be undone.
   */
  tone?: 'warning' | 'danger'
}
</script>

<script lang="ts">
let {
  approveLabel = 'Allow',
  children,
  decision,
  denyLabel = 'Deny',
  description,
  messages = (() => ({ approved: 'Allowed', denied: 'Denied' }))(),
  onApprove,
  onDeny,
  pending,
  title,
  tone = 'warning',
}: ApprovalCardProps = $props()
const uid = $props.id()
const joined = joinSlot(undefined, () => ({}))
const slots = {
  get default() {
    return children
  },
}
let card = $state<HTMLElement | null>(null)
const titleId = $derived(`${uid}-title`)
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'ApprovalCard',
    element: () => card,
    state: () => ({ title: title, decision: decision ?? '', pending: pending ?? '' }),
    actions: {},
    withholds: () => card,
  })
  release1 = () => {
    ran()
  }
}
watchEffect(effect1)
onDestroy(() => release1?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<section
    bind:this={card}
    class={styles.card}
    aria-labelledby={titleId}
    data-tone={tone}
    data-decision={decision}
    data-state={pending === undefined ? undefined : 'loading'}
    aria-busy={pending === undefined ? undefined : 'true'}
    data-member="approval-card"
    ><div class={styles.head}
      ><span class={styles.glyph}><Icon name={tone === 'danger' ? 'error' : 'warning'} /></span
      ><div class={styles.copy}
        ><p class={styles.title} id={titleId}>{title}</p
        >{#if description !== undefined}<p class={styles.description}>{description}</p>{/if
      }</div
    ></div
    >{#if slots.default}<div class={styles.details}>{@render children?.()}</div>{/if
    }{#if decision === undefined
      }<div class={styles.actions}
        ><Button
          variant="solid"
          tone={tone === 'danger' ? 'danger' : 'accent'}
          size="sm"
          label={approveLabel}
          loading={pending === 'approved'}
          disabled={pending === 'denied'}
          onClick={() => { onApprove?.() }}
        /><Button
          variant="outline"
          tone="neutral"
          size="sm"
          label={denyLabel}
          loading={pending === 'denied'}
          disabled={pending === 'approved'}
          onClick={() => { onDeny?.() }}
      /></div
    >{:else
      }<p class={styles.outcome}
        ><span class={styles.outcomeGlyph}
          ><Icon name={decision === 'approved' ? 'confirm' : 'denied'} size="sm"
        /></span
        >{decision === 'approved' ? messages.approved : messages.denied
      }</p
    >{/if
  }</section
>{/if
}{@render joined.end?.()}
